bool font_zh16_get_glyph(uint32_t codepoint, const uint16_t **rows)
{
    if (rows == NULL) {
        return false;
    }

    for (size_t i = 0; i < sizeof(s_glyphs) / sizeof(s_glyphs[0]); ++i) {
        if (s_glyphs[i].codepoint == codepoint) {
            *rows = s_glyphs[i].rows;
            return true;
        }
    }

    *rows = s_missing_glyph;
    return false;
}

const uint16_t *font_zh16_get_missing_glyph(void)
{
    return s_missing_glyph;
}
